/* ===== PARSEUR MOTORISATIONS ===== */
function parseMotors(str) {
  return String(str).split(";").map(s => s.trim()).filter(Boolean).map(s => {
    const p = s.split("|");
    return { name: p[0].trim(), fuel: FUEL_CODE[(p[1] || "E").trim()] || "essence", power: (p[2] || "").trim() ? (p[2].trim() + " ch") : "" };
  });
}
